IDS = ["b1", "b2", "b3", "α后端", "𝄞", "é"]
KEYS = ["k1", "k2", "用户", "\U0001F600"]
CIDS = ["c1", "c2", "c3"]

def rand_ops():
    ops = []
    now = 0
    for _ in range(random.randint(1, 40)):
        now += random.randint(0, 5)
        kind = random.choice([
            "add","remove","pick","open","close","get","hset","probe","hget",
            "chash","route","route3","ws","wg","cs","cr","cg","ds","dr","du","dg",
            "ss","ls","la","lg","os","oa","ot","og","oc","bp","bq",
            "mr","mg","mh","ms","mx","ce","fs","fx","fr","fb","fq","ts","tk","tg","tx",
        ])
        bid = random.choice(IDS); cid = random.choice(CIDS); key = random.choice(KEYS)
        flow = ["10.0.0.1", 8080, "10.0.0.2", 80, random.choice(["tcp","udp"])]
        w = random.randint(1,100); d = random.randint(0,100)
        if kind=="add": ops.append({"op":"add","id":bid,"weight":w} if random.random()<.5 else {"op":"add","id":bid,"weight":w,"d":d,"now":now})
        elif kind=="remove": ops.append({"op":"remove","id":bid})
        elif kind=="pick": ops.append({"op":"pick"})
        elif kind=="open": ops.append({"op":"open","cid":cid,"flow":flow,"now":now})
        elif kind=="close": ops.append({"op":"close","cid":cid,"now":now})
        elif kind=="get": ops.append({"op":"get","cid":cid})
        elif kind=="hset": ops.append({"op":"hset","id":bid,"fail":random.randint(1,100),"success":random.randint(1,100)})
        elif kind=="probe": ops.append({"op":"probe","id":bid,"ok":random.random()<.5,"now":now})
        elif kind=="hget": ops.append({"op":"hget","id":bid})
        elif kind=="chash": ops.append({"op":"chash","vnodes":random.randint(1,1024)})
        elif kind=="route": ops.append({"op":"route","key":key})
        elif kind=="route3": ops.append({"op":"route","key":key,"now":now})
        elif kind=="ws": ops.append({"op":"ws","id":bid,"weight":w,"d":d,"now":now})
        elif kind=="wg": ops.append({"op":"wg","id":bid,"now":now})
        elif kind=="cs": ops.append({"op":"cs","id":bid,"n":5,"m":2,"r":50,"w":10,"q":2})
        elif kind=="cr": ops.append({"op":"cr","id":bid,"ok":random.random()<.5,"now":now})
        elif kind=="cg": ops.append({"op":"cg","id":bid,"now":now})
        elif kind=="ds": ops.append({"op":"ds","id":bid,"t":random.randint(1,1000)})
        elif kind in ("dr","du","dg"): ops.append({"op":kind,"id":bid,"now":now})
        elif kind=="ss": ops.append({"op":"ss","ttl":random.randint(1,1000)})
        elif kind=="ls": ops.append({"op":"ls","scope":random.choice("BCS"),"id":bid,"r":random.randint(1,100),"b":random.randint(1,100),"now":now})
        elif kind=="la": ops.append({"op":"la","c":"cli","s":"svc","key":key,"now":now})
        elif kind=="lg": ops.append({"op":"lg","scope":random.choice("BCS"),"id":bid,"now":now})
        elif kind=="os": ops.append({"op":"os","cap":4,"q":3,"ttl":20})
        elif kind=="oa": ops.append({"op":"oa","cid":cid,"flow":flow,"c":"cli","s":"svc","key":key,"now":now})
        elif kind=="ot": ops.append({"op":"ot","now":now})
        elif kind=="og": ops.append({"op":"og"})
        elif kind=="oc": ops.append({"op":"oc","cid":cid})
        elif kind=="bp": ops.append({"op":"bp","low":1,"high":2})
        elif kind=="bq": ops.append({"op":"bq"})
        elif kind=="mr": ops.append({"op":"mr","id":bid,"ok":random.random()<.5,"ms":random.randint(0,2000),"retries":random.randint(0,3),"remaps":random.randint(0,3),"now":now})
        elif kind=="mg": ops.append({"op":"mg","id":bid,"now":now})
        elif kind=="mh": ops.append({"op":"mh","id":bid,"from":0,"to":now//60,"now":now})
        elif kind=="ms": ops.append({"op":"ms","id":bid,"now":now})
        elif kind=="mx": ops.append({"op":"mx","id":bid,"from":0,"to":now//60,"now":now})
        elif kind=="ce": ops.append({"op":"ce"})
        elif kind=="fs": ops.append({"op":"fs","id":bid,"k":random.choice(["D","F","S"]),"a":now,"z":now+50,"v":random.randint(1,10)} if random.random()<.7 else {"op":"fs","id":bid,"k":"D","a":now,"z":now+50,"v":0})
        elif kind=="fx": ops.append({"op":"fx","cid":cid,"flow":flow,"key":key,"timeout":random.randint(0,10),"now":now})
        elif kind=="fr": ops.append({"op":"fr","cid":cid,"flow":flow,"key":key,"timeout":random.randint(0,10),"max":random.randint(1,5),"now":now})
        elif kind=="fb": ops.append({"op":"fb","items":[{"id":i,"k":"D","a":now,"z":now+50,"v":0} for i in random.sample(IDS, random.randint(0,3))]})
        elif kind=="fq": ops.append({"op":"fq","now":now})
        elif kind=="ts": ops.append({"op":"ts","ttl":random.randint(1,1000)})
        elif kind=="tk": ops.append({"op":"tk","cid":cid,"now":now})
        elif kind=="tg": ops.append({"op":"tg","cid":cid,"now":now})
        elif kind=="tx": ops.append({"op":"tx","now":now})
    return {"ops": ops}

def run(prog, data):
    p = subprocess.run([sys.executable, prog, "run"], input=data, capture_output=True)
    return p.returncode, p.stdout, p.stderr

mismatch = 0
for i in range(3000):
    data = json.dumps(rand_ops(), ensure_ascii=False).encode("utf-8")
    a = run("/tmp/orig.py", data)
    b = run("balancer.py", data)
    if a != b:
        mismatch += 1
        print("MISMATCH", i, data[:300])
        print(" old:", a)
        print(" new:", b)
        if mismatch > 3: break
print("done, mismatches =", mismatch)
